from queueing import payload

def submit(owner, enqueue, batch_size=20):
    # Validate batch_size: must be integer between 1 and 100
    # Note: bool is a subclass of int in Python, so we must check for it explicitly first
    if isinstance(batch_size, bool) or not isinstance(batch_size, int) or batch_size < 1 or batch_size > 100:
        raise ValueError("batch_size must be an integer between 1 and 100")
    return enqueue(payload(owner, batch_size))

def payload(owner):
    """Legacy behavior - payloads without batch_size will use 20 in worker."""
    return {"owner":owner}

def payload_full(owner, batch_size=20):
    """New behavior - includes batch_size in the payload."""
    return {"owner":owner, "batch_size":batch_size}

def execute(task, process):
    # Use batch_size from payload if present, otherwise default to 20 (legacy behavior)
    batch_size = task.get("batch_size", 20)
    return process(task["owner"], batch_size)
